import hashlib
import math

class BloomFilter:
    """A Bloom Filter implementation to test membership with a given false positive rate.

    This class uses a bit array to store the presence of items and hashes to determine 
    the indices where items are to be stored. The optimal size of the bit array and 
    the number of hash functions are computed based on the expected number of items 
    and the desired false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        if expected_items <= 0:
            raise ValueError("Expected items must be greater than zero.")
        if not (0 < false_positive_rate < 1):
            raise ValueError("False positive rate must be between 0 and 1.")

        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        # Calculate the size of the bit array and the number of hash functions
        self.size = self._optimal_size()
        self.hash_count = self._optimal_hash_count()

        self.bit_array = [0] * self.size

    def _optimal_size(self) -> int:
        """Calculate the optimal size of the bit array."""
        return math.ceil((self.expected_items * math.log(self.false_positive_rate)) / math.log(1 / (math.pow(2, math.log(2)))))

    def _optimal_hash_count(self) -> int:
        """Calculate the optimal number of hash functions."""
        return math.ceil((self.size / self.expected_items) * math.log(2))

    def _hashes(self, item: str) -> list:
        """Generate hash indices for the given item."""
        hashes = []
        for i in range(self.hash_count):
            hash_digest = hashlib.md5(f"{item}{i}".encode()).hexdigest()
            index = int(hash_digest, 16) % self.size
            hashes.append(index)
        return hashes

    def add(self, item: str) -> None:
        """Add an item to the Bloom filter."""
        for index in self._hashes(item):
            self.bit_array[index] = 1

    def contains(self, item: str) -> bool:
        """Check if the Bloom filter contains an item."""
        return all(self.bit_array[index] for index in self._hashes(item))

